/**
 * The game's own logo - SECRET RECIPE / ทายวัตถุดิบลับ.
 *
 * It replaces a line of text and an emoji at the top of the page, so it has
 * to carry the same meaning to somebody who cannot see it: the `<img>` keeps
 * its `<h1>` and says in `alt` what the picture says in letters.
 *
 * webp at 680px, quality 72, like everything else here - 72 KB, against the
 * 320 KB the same drawing costs as a PNG with its transparency intact. The
 * page is handed to a WebView, a WebView is a browser, and browsers have read
 * webp for years.
 */
export const GAME_LOGO = 'data:image/webp;base64,';
